const menu=document.getElementById('menu'),nav=document.getElementById('nav');if(menu&&nav){menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation')});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}))}
const year=document.getElementById('year');if(year)year.textContent=new Date().getFullYear();
const views={learner:{kicker:'LEARNER EXPERIENCE / 01',title:'Find a path that fits your pace.',text:'Explore a clear next step, practice a skill, and ask for help when you need it. AI suggestions can offer direction; you stay in control of your journey.',items:['Flexible, modular learning paths','Practice and reflection in one flow','Accessibility and learner choice at the center'],label:'MY LEARNING SPACE',small:'FOUNDATIONS · UNIT 02',task:'Make sense of the big picture',next:'Try a short practice activity',progress:'63%',foot:['◌  Progress is yours to share','Help is always human']},educator:{kicker:'EDUCATOR EXPERIENCE / 02',title:'Support each learner with better context.',text:'Bring progress, questions, and learning resources into one view. Use AI-assisted summaries as a starting point, then add your own expertise.',items:['See where learners are progressing','Share feedback and recommended resources','Keep educator judgment in every decision'],label:'EDUCATOR OVERVIEW',small:'COHORT · WEEK 04',task:'Review concept understanding',next:'Share a worked example',progress:'72%',foot:['◌  Learner context stays visible','Educator insight leads']},organization:{kicker:'ORGANIZATION EXPERIENCE / 03',title:'Connect programs across your ecosystem.',text:'Coordinate learning experiences across teams, content, and tools. Understand engagement and outcomes while keeping measures purposeful.',items:['Connect existing learning resources','Coordinate cross-team learning programs','Review meaningful progress signals'],label:'PROGRAM SPACE',small:'DIGITAL SKILLS · COHORT A',task:'Build confidence with digital tools',next:'Open the next learning module',progress:'48%',foot:['◌  Privacy-aware program insight','People before metrics']}};
const tabs=document.querySelectorAll('.experience-tab');function renderView(key){const data=views[key],panel=document.getElementById('experiencePanel');if(!panel)return;panel.innerHTML=`<div class="experience-copy"><div class="experience-kicker">${data.kicker}</div><h3>${data.title}</h3><p>${data.text}</p><ul>${data.items.map(item=>`<li>${item}</li>`).join('')}</ul></div><div class="experience-visual"><div class="path-window"><div class="path-head"><span>${data.label}</span><b>Today <i>⌄</i></b></div><div class="path-title"><small>${data.small}</small><strong>${data.task}</strong><span>Learning progress</span></div><div class="path-progress"><i style="width:${data.progress}"></i></div><div class="path-next"><span>✧</span><div><small>A SUGGESTED NEXT STEP</small><b>${data.next}</b></div><a href="#demo">→</a></div><div class="path-footer"><span>${data.foot[0]}</span><span>${data.foot[1]}</span></div></div></div>`;tabs.forEach(tab=>{const active=tab.dataset.view===key;tab.classList.toggle('active',active);tab.setAttribute('aria-selected',String(active))})}tabs.forEach(tab=>tab.addEventListener('click',()=>renderView(tab.dataset.view)));
const suggestions={climate:{title:'Explore climate systems',steps:[['Start with a visual overview','See how atmosphere, ocean, land, and life interact.'],['Check your understanding','Match key terms with a simple interactive model.'],['Apply the idea','Explore a local example and reflect on the evidence.']]},coding:{title:'Build a coding foundation',steps:[['Meet the building blocks','Explore variables, instructions, and simple logic.'],['Practice by changing code','Try a small example and see what changes.'],['Create a mini project','Combine what you learned in a guided challenge.']]},literacy:{title:'Grow digital confidence',steps:[['Start with online basics','Explore safe browsing, accounts, and trusted sources.'],['Practice a useful task','Follow a guided example at your own pace.'],['Reflect and build independence','Review what worked and choose a next skill.']]},finance:{title:'Learn everyday money skills',steps:[['Explore a core concept','Start with budgeting, saving, or comparing costs.'],['Work through an example','Apply the concept to a simple scenario.'],['Make a personal learning plan','Choose a next step based on your goals.']]}};
const build=document.getElementById('buildPath');if(build)build.addEventListener('click',()=>{const topic=document.getElementById('topic').value,style=document.getElementById('style').value,idea=suggestions[topic],styleNote={mixed:'A mix of concise reading and short practice activities.',visual:'Visual examples first, followed by a reflection prompt.',practice:'Hands-on practice first, supported by a short concept guide.'}[style],result=document.getElementById('pathResult');result.innerHTML=`<div class="path-step"><i>1</i><div><b>${idea.title}</b><small>${styleNote}</small></div></div>${idea.steps.map((step,index)=>`<div class="path-step"><i>${index+2}</i><div><b>${step[0]}</b><small>${step[1]}</small></div></div>`).join('')}`});
